'use client'

import { useEffect, useRef, useState, type ReactNode, type ElementType } from 'react'
import { Bell, BookOpen, CalendarDays, Check, ChevronRight, Clock3, FileText, GraduationCap, LayoutDashboard, LogIn, Menu, Plus, Search, Settings, ShieldCheck, Trash2, Upload, Users, X, Store, MessageCircle, Send, Paperclip, Sparkles, Brain, ArrowUp, Mail, Phone, Headphones } from 'lucide-react'

type View = 'Landing' | 'About Course Rep' | 'Features' | 'How it works' | 'Professor Atlas info' | 'Overview' | 'My Courses' | 'Calendar' | 'Announcements' | 'Representative' | 'Marketplace' | 'Student Groups' | 'Direct Messages' | 'Professor Atlas' | 'Support Center' | 'Settings' | 'Login' | 'Register' | 'Onboarding' | 'Admin'

const courses = [
  { code: 'CSC 401', name: 'Software Engineering', color: 'indigo', unread: 2, next: 'Mon, 10:00 AM' },
  { code: 'CSC 403', name: 'Artificial Intelligence', color: 'blue', unread: 1, next: 'Tue, 12:00 PM' },
  { code: 'CSC 405', name: 'Computer Networks', color: 'amber', unread: 0, next: 'Wed, 9:00 AM' },
  { code: 'CSC 407', name: 'Information Security', color: 'slate', unread: 0, next: 'Thu, 2:00 PM' },
]
const announcements = [
  ['CSC 401', 'Lecture venue changed', 'Today\'s Software Engineering lecture will hold at Lecture Hall B instead of ICT Centre.', '12 min ago', 'Dr. Adaeze Okafor', true],
  ['CSC 403', 'Assignment submission deadline', 'Remember to submit your search algorithms assignment before Friday at 11:59 PM.', '2 hrs ago', 'Daniel Chukwu · Course Rep', false],
  ['Department', 'Departmental seminar scheduled', 'Join us this Friday for a conversation on building reliable systems in Africa.', 'Yesterday', 'Computer Science Department', false],
]

function Logo() { return <div className="brand"><span className="brand-mark"><GraduationCap /></span><span>Course Rep</span></div> }
function PageHeader({ title, subtitle, action }: { title: string; subtitle: string; action?: ReactNode }) { return <div className="page-heading"><div><p className="eyebrow">Course Rep workspace</p><h1>{title}</h1><p className="subheading">{subtitle}</p></div>{action}</div> }
function Panel({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`panel ${className}`}>{children}</section> }
function Pill({ children, tone = '' }: { children: React.ReactNode; tone?: string }) { return <span className={`course-pill ${tone}`}>{children}</span> }

function Dashboard({ go }: { go: (view: View) => void }) { return <>
  <PageHeader title="Good morning, Peter" subtitle="Here&apos;s what&apos;s happening with your academics today." action={<button className="primary-button" onClick={() => go('Calendar')}><CalendarDays /> View calendar</button>} />
  <div className="profile-strip"><div className="institution-logo">EU</div><div><strong>Example University</strong><span>Computer Science · 400 Level · 2026/2027 session</span></div><button className="text-button" onClick={() => go('Settings')}>Edit profile <ChevronRight /></button></div>
  <div className="stats-grid"><div className="stat-card"><div className="stat-icon purple"><BookOpen /></div><div><span>Enrolled courses</span><strong>4</strong><small>All courses active</small></div></div><div className="stat-card"><div className="stat-icon blue"><CalendarDays /></div><div><span>Upcoming lectures</span><strong>6</strong><small>Next one in 2 days</small></div></div><div className="stat-card"><div className="stat-icon amber"><FileText /></div><div><span>Pending assessments</span><strong>3</strong><small className="warning-text">1 due this week</small></div></div></div>
  <div className="dashboard-grid"><Panel><div className="panel-header"><div><h2>Important announcements</h2><p>Stay up to date with your courses</p></div><button className="text-button" onClick={() => go('Announcements')}>View all <ChevronRight /></button></div><div className="announcement-list">{announcements.map(([course, title, body, time, author, urgent]) => <article className={`announcement ${urgent ? 'urgent' : ''}`} key={String(title)}><div className="announcement-icon"><Bell /></div><div className="announcement-copy"><div className="announcement-meta"><Pill>{course}</Pill>{urgent && <Pill tone="urgent-pill">Urgent</Pill>}<span className="time">{time}</span></div><h3>{title}</h3><p>{body}</p><span className="author">{author}</span></div></article>)}</div></Panel><Panel className="lecture-panel"><div className="panel-header"><div><h2>Next lecture</h2><p>Your upcoming class</p></div><button className="round-arrow" onClick={() => go('Calendar')} aria-label="View timetable"><ChevronRight /></button></div><div className="lecture-date"><span>MON</span><strong>12</strong><small>OCT</small></div><div className="lecture-info"><Pill>CSC 401</Pill><h3>Software Engineering</h3><div><Clock3 /> 10:00 AM – 12:00 PM</div><div><span className="pin-dot" /> Lecture Hall B</div></div><div className="lecture-footer"><span>Dr. Adaeze Okafor</span><button className="text-button">Add to calendar</button></div></Panel></div>
  <div className="lower-grid"><Panel><div className="panel-header"><div><h2>Upcoming deadlines</h2><p>Keep your momentum going</p></div><button className="text-button" onClick={() => go('Calendar')}>See all <ChevronRight /></button></div><div className="deadline-list">{[['10','OCT','CSC 403','Search Algorithms Assignment','2 days left'],['16','OCT','CSC 405','Network Design Test','8 days left']].map((d) => <div className="deadline" key={String(d[3])}><div className="deadline-date"><strong>{d[0]}</strong><span>{d[1]}</span></div><div><Pill>{d[2]}</Pill><h3>{d[3]}</h3><p><Clock3 /> Due Friday, 11:59 PM</p></div><span className="status soon">{d[4]}</span></div>)}</div></Panel><Courses go={go} /><Panel className="marketplace-preview"><div className="panel-header"><div><h2>Student marketplace</h2><p>Useful finds from your campus community</p></div><button className="text-button" onClick={() => go('Marketplace')}>Browse all <ChevronRight /></button></div><div className="marketplace-preview-list"><button onClick={() => go('Marketplace')}><span className="market-preview-icon"><BookOpen /></span><span><strong>CSC 403 past questions</strong><small>Study materials · ₦2,500</small></span><ChevronRight /></button><button onClick={() => go('Marketplace')}><span className="market-preview-icon green"><Store /></span><span><strong>Scientific calculator</strong><small>Electronics · ₦8,000</small></span><ChevronRight /></button></div></Panel></div>
</> }
function Courses({ go }: { go: (view: View) => void }) { return <Panel><div className="panel-header"><div><h2>My courses</h2><p>4 active courses</p></div><button className="text-button" onClick={() => go('My Courses')}>View all <ChevronRight /></button></div><div className="course-list">{courses.map(c => <div className="course-row" key={c.code}><span className={`course-avatar ${c.color}`}>{c.code.split(' ')[1]}</span><div><strong>{c.code}</strong><span>{c.name}</span></div>{c.unread > 0 && <span className="unread">{c.unread}</span>}<span className="course-next"><CalendarDays /> {c.next}</span></div>)}</div></Panel> }
function CoursesPage({ go }: { go: (view: View) => void }) {
  const [query, setQuery] = useState('')
  const [showJoin, setShowJoin] = useState(false)
  const [joined, setJoined] = useState<string[]>([])
  const filtered = courses.filter(course => `${course.code} ${course.name}`.toLowerCase().includes(query.toLowerCase()))
  return <>
    <PageHeader title="My courses" subtitle="Your active courses for the 2026/2027 academic session." action={<button className="primary-button" onClick={() => setShowJoin(true)}><Plus /> Join a course</button>} />
    <div className="toolbar"><div className="top-search"><Search /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search courses..." aria-label="Search courses" /></div><button className="filter-button" onClick={() => setQuery('')}>All departments <ChevronRight /></button></div>
    <div className="course-cards">{filtered.map(c => <button className="course-card" key={c.code} onClick={() => go('Announcements')}><span className={`course-avatar ${c.color}`}>{c.code.split(' ')[1]}</span><span><strong>{c.code}</strong><b>{c.name}</b><small>Computer Science · 400 Level</small></span><span className="course-card-meta">{c.unread ? `${c.unread} unread` : 'Up to date'}<ChevronRight /></span></button>)}{filtered.length === 0 && <Panel><p>No courses match your search.</p></Panel>}</div>
    {showJoin && <div className="modal-backdrop" role="presentation" onMouseDown={event => event.target === event.currentTarget && setShowJoin(false)}><form className="event-dialog" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); setJoined(current => [...current, String(data.get('code'))]); setShowJoin(false) }}><div className="dialog-header"><div><p className="eyebrow">Courses</p><h2>Join a course</h2><p>Enter the course code provided by your department.</p></div><button type="button" className="icon-btn" onClick={() => setShowJoin(false)} aria-label="Close join course form"><X /></button></div><label>Course code<input name="code" required placeholder="e.g. CSC 409" /></label><div className="dialog-actions"><button type="button" className="secondary-button" onClick={() => setShowJoin(false)}>Cancel</button><button type="submit" className="primary-button"><Plus /> Join course</button></div></form></div>}
  </>
}
function CalendarPage() {
  const [showForm, setShowForm] = useState(false)
  const [viewMode, setViewMode] = useState<'Week' | 'List'>('Week')
  const [selectedDay, setSelectedDay] = useState('Mon 12')
  const [events, setEvents] = useState([{ title: 'Software Engineering', course: 'CSC 401', date: 'Mon 12', time: '10:00 AM – 12:00 PM', location: 'Lecture Hall B', tone: 'indigo-bar', removable: false }, { title: 'Artificial Intelligence', course: 'CSC 403', date: 'Mon 12', time: '2:00 PM – 4:00 PM', location: 'ICT Centre', tone: 'blue-bar', removable: false }])
  const [draft, setDraft] = useState({ title: '', date: 'Mon 12', start: '10:00', end: '11:00', location: '', course: 'Personal event' })
  const [draggedEvent, setDraggedEvent] = useState<string | null>(null)
  const visibleEvents = viewMode === 'List' ? events : events.filter(item => item.date === selectedDay)
  const moveEventToDay = (day: string) => { if (!draggedEvent) return; setEvents(current => current.map(item => item.title === draggedEvent ? { ...item, date: day } : item)); setSelectedDay(day); setDraggedEvent(null) }

  const addEvent = (event: React.FormEvent) => {
    event.preventDefault()
    if (!draft.title.trim()) return
    setEvents(current => [...current, { title: draft.title.trim(), course: draft.course, date: draft.date, time: `${draft.start} – ${draft.end}`, location: draft.location || 'No location', tone: 'amber-bar', removable: true }])
    setDraft({ title: '', date: 'Mon 12', start: '10:00', end: '11:00', location: '', course: 'Personal event' })
    setShowForm(false)
  }

  return <>
    <PageHeader title="Academic calendar" subtitle="Your lectures and deadlines for the week of October 12–18, 2026." action={<button className="primary-button" onClick={() => setShowForm(true)}><Plus /> Add event</button>} />
    <div className="calendar-tabs"><button className={viewMode === 'Week' ? 'active' : ''} onClick={() => setViewMode('Week')}>Week</button><button className={viewMode === 'List' ? 'active' : ''} onClick={() => setViewMode('List')}>List</button></div>
    <Panel className="schedule">{viewMode === 'Week' && <div className="week-row">{['Mon 12','Tue 13','Wed 14','Thu 15','Fri 16'].map(d => <button className={selectedDay === d ? 'active' : ''} onClick={() => setSelectedDay(d)} onDragOver={event => event.preventDefault()} onDrop={() => moveEventToDay(d)} key={d}><small>{d.split(' ')[0]}</small><strong>{d.split(' ')[1]}</strong></button>)}</div>}<div className="schedule-list">{visibleEvents.map((item, index) => <div className={`schedule-item ${draggedEvent === item.title ? 'is-dragging' : ''}`} key={`${item.title}-${index}`} draggable onDragStart={() => setDraggedEvent(item.title)} onDragEnd={() => setDraggedEvent(null)}><span className="schedule-time">{item.time.split(' ')[0]}<br/><small>{item.time.includes('PM') ? 'PM' : 'AM'}</small></span><div className={`schedule-bar ${item.tone}`}><Pill>{item.course}</Pill><strong>{item.title}</strong><span>{item.location} · {item.time}</span>{item.removable && <button className="event-remove" onClick={() => setEvents(current => current.filter(event => event !== item))} aria-label={`Remove ${item.title}`}><Trash2 /> Remove</button>}</div></div>)}</div>{visibleEvents.length === 0 && <div className="calendar-empty"><CalendarDays /><strong>No events scheduled</strong><span>Select another day or add a personal event.</span></div>}</Panel>
    {showForm && <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && setShowForm(false)}><form className="event-dialog" onSubmit={addEvent} aria-labelledby="event-title"><div className="dialog-header"><div><p className="eyebrow">Calendar</p><h2 id="event-title">Add an event</h2><p>Keep a personal reminder alongside your lectures.</p></div><button type="button" className="icon-btn" onClick={() => setShowForm(false)} aria-label="Close add event form"><X /></button></div><label>Event title<input required autoFocus value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} placeholder="e.g. Study group" /></label><div className="event-field-grid"><label>Date<select value={draft.date} onChange={event => setDraft({ ...draft, date: event.target.value })}>{['Mon 12','Tue 13','Wed 14','Thu 15','Fri 16'].map(day => <option key={day}>{day}</option>)}</select></label><label>Course<select value={draft.course} onChange={event => setDraft({ ...draft, course: event.target.value })}><option>Personal event</option>{courses.map(course => <option key={course.code}>{course.code}</option>)}</select></label></div><div className="event-field-grid"><label>Start time<input type="time" value={draft.start} onChange={event => setDraft({ ...draft, start: event.target.value })} /></label><label>End time<input type="time" value={draft.end} onChange={event => setDraft({ ...draft, end: event.target.value })} /></label></div><label>Location<input value={draft.location} onChange={event => setDraft({ ...draft, location: event.target.value })} placeholder="Optional" /></label><div className="dialog-actions"><button type="button" className="secondary-button" onClick={() => setShowForm(false)}>Cancel</button><button type="submit" className="primary-button"><Plus /> Save event</button></div></form></div>}
  </>
}
function AnnouncementsPage() {
  const [filter, setFilter] = useState<'All' | 'Unread' | 'Urgent'>('All')
  const [read, setRead] = useState(false)
  const items = [...announcements, ...announcements].filter(item => filter === 'All' || (filter === 'Urgent' ? item[5] : !read))
  return <><PageHeader title="Announcements" subtitle="Everything important from your courses and department." action={<button className="primary-button" onClick={() => setRead(true)}><Bell /> Mark all read</button>} /><div className="filter-tabs">{(['All', 'Unread', 'Urgent'] as const).map(name => <button key={name} className={filter === name ? 'active' : ''} onClick={() => setFilter(name)}>{name} <span>{name === 'All' ? 8 : name === 'Unread' ? (read ? 0 : 3) : 1}</span></button>)}</div><Panel><div className="announcement-list">{items.map(([course,title,body,time,author,urgent],i)=><article className={`announcement ${urgent?'urgent':''}`} key={`${title}-${i}`}><div className="announcement-icon"><Bell /></div><div className="announcement-copy"><div className="announcement-meta"><Pill>{course}</Pill>{urgent&&<Pill tone="urgent-pill">Urgent</Pill>}<span className="time">{time}</span></div><h3>{title}</h3><p>{body}</p><span className="author">{author}</span></div>{!read && <span className="unread-dot" />}</article>)}{items.length === 0 && <p>No announcements in this view.</p>}</div></Panel></>
}
function RepresentativePage() {
  const [modal, setModal] = useState<'announcement' | 'timetable' | 'material' | null>(null)
  const [announcement, setAnnouncement] = useState({ title: '', message: '', course: 'CSC 401' })
  const [schedule, setSchedule] = useState({ course: 'CSC 401', day: 'Monday', time: '10:00 AM', venue: '' })
  const [material, setMaterial] = useState({ title: '', type: 'Lecture notes' })
  const [activity, setActivity] = useState(['Class representative access approved', 'CSC 401 lecture venue confirmed'])
  const close = () => setModal(null)
  const submitAnnouncement = (event: React.FormEvent) => { event.preventDefault(); if (!announcement.title.trim() || !announcement.message.trim()) return; setActivity(current => [`Announcement posted: ${announcement.title.trim()}`, ...current]); setAnnouncement({ title: '', message: '', course: 'CSC 401' }); close() }
  const submitSchedule = (event: React.FormEvent) => { event.preventDefault(); setActivity(current => [`Timetable updated: ${schedule.course} · ${schedule.day}`, ...current]); close() }
  const submitMaterial = (event: React.FormEvent) => { event.preventDefault(); if (!material.title.trim()) return; setActivity(current => [`Material added: ${material.title.trim()}`, ...current]); setMaterial({ title: '', type: 'Lecture notes' }); close() }
  return <><PageHeader title="Representative centre" subtitle="Manage the courses you are verified to represent." action={<Pill tone="verified-pill"><ShieldCheck /> Verified representative</Pill>} /><Panel className="rep-hero"><div><Pill tone="verified-pill"><ShieldCheck /> Approved for 2026/2027</Pill><h2>Your class, coordinated.</h2><p>Keep classmates informed with trusted updates, schedules, assessments, and resources.</p></div><button className="primary-button" onClick={() => setModal('announcement')}><Plus /> New announcement</button></Panel><div className="quick-grid"><button onClick={() => setModal('announcement')}><Bell /><strong>Post announcement</strong><span>Share an update with your class</span></button><button onClick={() => setModal('timetable')}><CalendarDays /><strong>Manage timetable</strong><span>Update lecture schedules</span></button><button onClick={() => setModal('material')}><Upload /><strong>Upload material</strong><span>Add notes or past questions</span></button></div><div className="rep-columns"><Panel><div className="panel-header"><div><h2>Verification status</h2><p>Your representative access is active</p></div><span className="status verified">Approved</span></div><div className="verification-row"><Check /> Application approved by Department of Computer Science <span>Oct 4, 2026</span></div></Panel><Panel><div className="panel-header"><div><h2>Recent activity</h2><p>Changes made from this centre</p></div></div><div className="rep-activity">{activity.slice(0, 4).map((item, index) => <div key={`${item}-${index}`}><Check /><span>{item}</span><small>{index === 0 ? 'Just now' : 'Recently'}</small></div>)}</div></Panel></div>{modal && <div className="modal-backdrop" role="presentation" onMouseDown={event => event.target === event.currentTarget && close()}><form className="event-dialog representative-dialog" onSubmit={modal === 'announcement' ? submitAnnouncement : modal === 'timetable' ? submitSchedule : submitMaterial}><div className="dialog-header"><div><p className="eyebrow">Representative tools</p><h2>{modal === 'announcement' ? 'Post an announcement' : modal === 'timetable' ? 'Update timetable' : 'Upload course material'}</h2><p>Keep your classmates informed with accurate course details.</p></div><button type="button" className="icon-btn" onClick={close} aria-label="Close dialog"><X /></button></div>{modal === 'announcement' && <><label>Course<select value={announcement.course} onChange={event => setAnnouncement({ ...announcement, course: event.target.value })}><option>CSC 401</option><option>CSC 403</option><option>CSC 405</option><option>CSC 407</option></select></label><label>Title<input required value={announcement.title} onChange={event => setAnnouncement({ ...announcement, title: event.target.value })} placeholder="e.g. Venue changed for tomorrow's lecture" /></label><label>Message<textarea required rows={4} value={announcement.message} onChange={event => setAnnouncement({ ...announcement, message: event.target.value })} placeholder="Write a clear update for your class..." /></label></>}{modal === 'timetable' && <><label>Course<select value={schedule.course} onChange={event => setSchedule({ ...schedule, course: event.target.value })}><option>CSC 401</option><option>CSC 403</option><option>CSC 405</option><option>CSC 407</option></select></label><label>Day<select value={schedule.day} onChange={event => setSchedule({ ...schedule, day: event.target.value })}><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option></select></label><label>Time<input required value={schedule.time} onChange={event => setSchedule({ ...schedule, time: event.target.value })} /></label><label>Venue<input required value={schedule.venue} onChange={event => setSchedule({ ...schedule, venue: event.target.value })} placeholder="e.g. Lecture Hall B" /></label></>}{modal === 'material' && <><label>Material title<input required value={material.title} onChange={event => setMaterial({ ...material, title: event.target.value })} placeholder="e.g. CSC 401 revision notes" /></label><label>Material type<select value={material.type} onChange={event => setMaterial({ ...material, type: event.target.value })}><option>Lecture notes</option><option>Past questions</option><option>Study guide</option></select></label><div className="upload-dropzone"><Upload /><span>File upload is ready for connection</span><small>Demo mode: the material title will be saved</small></div></>}<div className="dialog-actions"><button type="button" className="secondary-button" onClick={close}>Cancel</button><button type="submit" className="primary-button"><Check /> Save changes</button></div></form></div>}</> }
function ProfessorAtlasPage() {
  const [question, setQuestion] = useState('')
  const [asked, setAsked] = useState<string[]>([])
  const askProfessor = (event: React.FormEvent) => { event.preventDefault(); if (!question.trim()) return; setAsked(current => [...current, question.trim()]); setQuestion('') }
  return <>
    <PageHeader title="Professor Atlas" subtitle="A thoughtful guide for understanding your academic record." />
    <div className="atlas-hero"><div className="atlas-orb"><Brain /></div><div><Pill tone="atlas-pill"><Sparkles /> Academic insight</Pill><h2>Meet your academic analyst.</h2><p>Professor Atlas reviews the records you&apos;ve uploaded and helps you spot patterns, plan ahead, and ask better questions.</p></div><div className="atlas-status"><span /> Record connected<small>Last synced today</small></div></div>
    <div className="atlas-grid"><Panel className="atlas-chat"><div className="panel-header"><div><h2>Ask Professor Atlas</h2><p>Answers are based on your uploaded academic record.</p></div><span className="atlas-live"><Sparkles /> Ready</span></div><div className="atlas-messages"><div className="atlas-message atlas-message-ai"><span className="atlas-avatar"><Brain /></span><div><strong>Professor Atlas</strong><p>Hello Peter. I&apos;ve reviewed your current record. Ask me about your grades, course progress, or what to prioritize next.</p></div></div>{asked.map((item, index) => <div className="atlas-message atlas-message-student" key={`${item}-${index}`}><span className="atlas-avatar">PE</span><div><strong>You</strong><p>{item}</p></div></div>)}{asked.length > 0 && <div className="atlas-message atlas-message-ai"><span className="atlas-avatar"><Brain /></span><div><strong>Professor Atlas</strong><p>Based on the sample record, CSC 403 is the best place to focus next. Your current pace is steady, and a focused review session before Friday should help protect your momentum.</p></div></div>}</div><form className="atlas-composer" onSubmit={askProfessor}><input value={question} onChange={event => setQuestion(event.target.value)} placeholder="Ask about your academic record..." aria-label="Ask Professor Atlas" /><button className="primary-button" aria-label="Ask Professor Atlas"><ArrowUp /></button></form></Panel><Panel className="atlas-record"><div className="panel-header"><div><h2>Record snapshot</h2><p>Information Professor Atlas can use</p></div><FileText /></div><div className="record-score"><span>Current average</span><strong>3.68</strong><small>Strong academic standing</small></div><div className="record-list"><div><span>Completed credits</span><strong>72 / 120</strong></div><div><span>Active courses</span><strong>4</strong></div><div><span>Pending assessments</span><strong>3</strong></div></div><div className="atlas-suggestions"><span>Try asking</span><button onClick={() => setQuestion('Which course should I prioritize this week?')}>What should I prioritize?</button><button onClick={() => setQuestion('How is my academic progress trending?')}>How is my progress trending?</button></div></Panel></div>
  </>
}
function SupportPage() { return <><PageHeader title="Support center" subtitle="We&apos;re here to help you stay on track with your academic journey." /><div className="support-hero"><div className="support-hero-icon"><Headphones /></div><div><p className="eyebrow">Need a hand?</p><h2>Let&apos;s get things sorted.</h2><p>Reach out to the Course Rep support team for help with your account, courses, messages, or anything else in your workspace.</p></div></div><div className="support-grid"><Panel className="support-card"><div className="support-icon support-email"><Mail /></div><div><p className="eyebrow">Email support</p><h2>Send us an email</h2><p>For detailed questions or issues that need a little more context.</p><a href="mailto:support@courserep.app">support@courserep.app</a><small>We usually reply within one business day.</small></div></Panel><Panel className="support-card"><div className="support-icon support-phone"><Phone /></div><div><p className="eyebrow">Phone support</p><h2>Talk to our team</h2><p>For urgent account or access issues, give us a call during support hours.</p><a href="tel:+2348001234567">+234 800 123 4567</a><small>Monday–Friday, 9:00 AM–5:00 PM WAT</small></div></Panel></div><Panel className="support-note"><strong>Before you contact us</strong><span>Include your university, level, and a short description of the issue so we can help you faster.</span></Panel></> }
function SettingsPage({ go }: { go: (view: View) => void }) { return <><PageHeader title="Profile & settings" subtitle="Manage your academic profile, preferences, and account security." /><div className="settings-layout"><Panel><div className="settings-profile"><span className="avatar profile-avatar">PE</span><div><h2>Peter Chijioke</h2><p>peter.chijioke@example.edu.ng</p><Pill tone="verified-pill">Student · 400 Level</Pill></div><button className="text-button">Edit profile</button></div><div className="settings-list"><button><span><Users /> Academic profile</span><ChevronRight /></button><button><span><Bell /> Notifications</span><span className="toggle on">On</span></button><button><span><ShieldCheck /> Account security</span><ChevronRight /></button><button onClick={() => go('Login')}><span className="danger">Log out</span><ChevronRight /></button></div></Panel><Panel><div className="panel-header"><div><h2>Academic information</h2><p>Used to personalize your experience</p></div></div><div className="info-grid"><label>Institution<strong>Example University</strong></label><label>Department<strong>Computer Science</strong></label><label>Academic level<strong>400 Level</strong></label><label>Academic session<strong>2026/2027</strong></label></div></Panel></div></> }
